window.kbPageData["cards/d3565c6ae694ba8d80961da3"] = {"qs":{"江苏 2024 C类 行测#1":{"paper":"江苏 2024 C类 行测","n":1,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",1],"m":[],"task":"辨析中国式现代化在任务难度、发展道路和文明形态方面的特征。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是中国式现代化的理论内涵与意义。"},"links":[{"id":"k-249172c9fdc77571","label":"超大人口规模对中国式现代化任务和难度的影响","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"人口规模不同，现代化的任务就不同","why":"十四亿多人口整体迈入现代化，决定了任务的特殊性及其历史性的艰巨程度。","origin":"逐题标记"},{"id":"k-fb1ce1e7a6289679","label":"中国式现代化坚持独立自主、走和平发展道路","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"中国式现代化坚持独立自主、自力更生","why":"独立自主与和平发展共同界定中国式现代化的发展道路。","origin":"逐题标记"},{"id":"k-10613bff850024e3","label":"创造人类文明新形态是中国式现代化的本质要求","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"创造人类文明新形态。","why":"党的二十大报告将创造人类文明新形态列为中国式现代化的本质要求。","origin":"逐题标记"}],"stem":"党的二十大报告指出，中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色。关于中国式现\n代化的内涵和意义，下列表述正确的是：\n①有与世界各国现代化相同的任务\n②是人类历史上难度最大的现代化\n③是独立自主、和平发展的现代化\n④创造了一种全新的人类文明形态","options":["①②③","①②④","①③④","②③④"],"answer":"D","analysis":"1. 正确答案：D\n解析：\n本题考查政治常识。\n①错误，②正确，习近平总书记在《中国式现代化是强国建设、民族复兴的康庄大道》的文章中指出：“第一，人口\n规模巨大的现代化。这是中国式现代化的显著特征。人口规模不同，现代化的任务就不同，其艰巨性、复杂性就不\n同，发展途径和推进方式也必然具有自己的特点。现在，全球进入现代化的国家也就20多个，总人口10亿左右。中\n国14亿多人口整体迈入现代化，规模超过现有发达国家人口的总和，将极大地改变现代化的世界版图。这是人类历\n史上规模最大的现代化，也是难度最大的现代化。”\n③正确，习近平总书记在《中国式现代化是强国建设、民族复兴的康庄大道》的文章中指出：“第五，走和平发展道\n路的现代化。坚持和平发展，在坚定维护世界和平与发展中谋求自身发展，又以自身发展更好维护世界和平与发\n展，推动构建人类命运共同体，是中国式现代化的突出特征······中国式现代化坚持独立自主、自力更生，依靠全体\n人民的辛勤劳动和创新创造发展壮大自己，通过激发内生动力与和平利用外部资源相结合的方式来实现国家发展，\n不以任何形式压迫其他民族、掠夺他国资源财富，而是为广大发展中国家提供力所能及的支持和帮助。”\n④正确，党的二十大报告中“三、新时代新征程中国共产党的使命任务”指出：“中国式现代化的本质要求是：坚持中\n国共产党领导，坚持中国特色社会主义，实现高质量发展，发展全过程人民民主，丰富人民精神世界，实现全体人\n民共同富裕，促进人与自然和谐共生，推动构建人类命运共同体，创造人类文明新形态。”\n故②③④表述正确。\n故正确答案为D。\n【考点】\n理论与政策-其他,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false},"江苏 2024 C类 行测#2":{"paper":"江苏 2024 C类 行测","n":2,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",1],"m":[],"task":"依据2023年全国生态环境保护大会讲话辨析新时代生态文明建设的成就、治理要求和压力现状。","current_affairs":{"state":"是","event":"全国生态环境保护大会关于新时代生态文明建设成就、形势与治理要求的讲话","year":2023,"basis":"作答需要辨认大会讲话对治理要求和生态环境压力现状的具体表述。"},"links":[{"id":"k-1d5df4f144112e04","label":"生态文明思想","catalog_id":"49e1ee3f5a2cb325","type":"事实与事件","role":"直接考查","field":"answer","quote":"实现由实践探索到科学理论指导的重大转变","why":"形成新时代中国特色社会主义生态文明思想体现了生态文明建设由实践探索转向科学理论指导。","origin":"逐题标记"},{"id":"k-90aac7b0cf5638bf","label":"山水林田湖草沙一体化保护和系统治理","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"要坚持山水林田湖草沙一体化保护和系统治理","why":"讲话提出生态要素一体化保护和系统治理的要求。","origin":"逐题标记"},{"id":"k-8ce8da4833e746e4","label":"2023年生态环境保护的结构性、根源性、趋势性压力尚未根本缓解","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"趋势性压力\n尚未根本缓解","why":"讲话对三类压力的阶段性判断是辨析建设成就的依据。","origin":"逐题标记"},{"id":"k-489820be3080ddbf","label":"新时代生态文明建设由被动应对转向主动作为","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"实现由被动应对到主动作为的重大转变","why":"这一转变体现了全党全国推进生态文明建设的自觉性和主动性增强。","origin":"逐题标记"}],"stem":"2023年7月，习近平总书记在全国生态环境保护大会上指出，新时代生态文明建设的成就举世瞩目，成为新时代党\n和国家事业取得历史性成就、发生历史性变革的显著标志。关于新时代生态文明建设的成就，下列表述正确的是：\n①形成了新时代中国特色社会主义生态文明思想\n②实现了山水林田湖草沙的一体化保护和系统治理\n③根本缓解了生态环境保护的结构性、根源性、趋势性压力\n④增强了全党全国推进生态文明建设的自觉性主动性","options":["①②③","①②④","①③④","②③④"],"answer":"B","analysis":"2. 正确答案：B\n解析：\n本题考查政治常识。\n①正确：习近平总书记在全国生态环境保护大会上的讲话中强调，不断深化对生态文明建设规律的认识，形成新时\n代中国特色社会主义生态文明思想，实现由实践探索到科学理论指导的重大转变。经过顽强努力，我国天更蓝、地\n更绿、水更清，万里河山更加多姿多彩。\n②正确：习近平总书记在全国生态环境保护大会上的讲话中指出，要坚持山水林田湖草沙一体化保护和系统治理，\n构建从山顶到海洋的保护治理大格局，综合运用自然恢复和人工修复两种手段，因地因时制宜、分区分类施策，努\n力找到生态保护修复的最佳解决方案。\n③错误：习近平总书记在全国生态环境保护大会上的讲话中强调，我国生态环境保护结构性、根源性、趋势性压力\n尚未根本缓解。我国经济社会发展已进入加快绿色化、低碳化的高质量发展阶段，生态文明建设仍处于压力叠加、\n负重前行的关键期。必须以更高站位、更宽视野、更大力度来谋划和推进新征程生态环境保护工作，谱写新时代生\n态文明建设新篇章。\n④正确：习近平总书记在全国生态环境保护大会上的讲话中强调，坚持转变观念、压实责任，不断增强全党全国推\n进生态文明建设的自觉性主动性，实现由被动应对到主动作为的重大转变。\n故正确答案为B。\n【考点】\n生态文明建设,重大会议及讲话","figs":[],"state":"待核","notes":["参考答案将②列为成就，解析引文只支持“要坚持”一体化保护和系统治理，题干表述为“实现了”。"],"domains":["政治理论","生态环境"],"nature":"知识题","current":true},"江苏 2024 C类 行测#3":{"paper":"江苏 2024 C类 行测","n":3,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",1],"m":[],"task":"辨认第三届“一带一路”国际合作高峰论坛宣布的八项行动及科技创新行动计划的实施阶段。","current_affairs":{"state":"是","event":"第三届“一带一路”国际合作高峰论坛宣布支持高质量共建“一带一路”的八项行动","year":2023,"basis":"作答需要掌握此次论坛宣布的具体行动和科技创新行动计划的实施口径。"},"links":[{"id":"k-210922a2598d0ba7","label":"第三届“一带一路”国际合作高峰论坛宣布的高质量共建八项行动","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"立体互联互通网络、支持建设开放型世界经济","why":"构建立体互联互通网络、支持建设开放型世界经济和完善国际合作机制均列入八项行动。","origin":"逐题标记"},{"id":"k-83fc3e52381c71f6","label":"第三届“一带一路”国际合作高峰论坛宣布继续实施科技创新行动计划","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"中方将继续实施“一带一路”科技创新行动计划","why":"“继续实施”明确了科技创新行动计划在此次论坛部署中的实施阶段。","origin":"逐题标记"}],"stem":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛上宣布，中国将采取行动支持高质量共建“一\n带一路”。关于中国将采取的行动，下列表述正确的有：\n①支持建设开放型世界经济\n②完善“一带一路”国际合作机制\n③构建“一带一路”立体互联互通网络\n④启动“一带一路”科技创新行动计划","options":["①②③","①②④","②③④","①③④"],"answer":"A","analysis":"3. 正确答案：A\n解析：\n本题考查政治常识。\n\n①②③正确：2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上发表了题为《建设开放\n包容、互联互通、共同发展的世界》的主旨演讲，宣布了中国支持高质量共建“一带一路”的八项行动，包括：构\n建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民\n间交往、建设廉洁之路、完善“一带一路”国际合作机制。\n④错误：习近平主席在讲话中指出，中方将继续实施“一带一路”科技创新行动计划，举办首届“一带一路”科技交流大\n会，未来5年把同各方共建的联合实验室扩大到100家，支持各国青年科学家来华短期工作。故“启动‘一带一路’科技\n创新行动计划”说法错误。\n故正确答案为A。\n【考点】\n和平外交建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true}},"materialFiles":{},"terms":{"k-249172c9fdc77571":{"id":"k-249172c9fdc77571","mode":"k","type":"观点与论证","title":"人口规模巨大的现代化","qs":[],"count":2},"k-fb1ce1e7a6289679":{"id":"k-fb1ce1e7a6289679","mode":"k","type":"观点与论证","title":"中国式现代化的独立自主与和平发展","qs":[],"count":3},"k-10613bff850024e3":{"id":"k-10613bff850024e3","mode":"k","type":"观点与论证","title":"创造人类文明新形态","qs":[],"count":3},"k-1d5df4f144112e04":{"id":"k-1d5df4f144112e04","mode":"k","type":"事实与事件","title":"习近平生态文明思想","qs":[],"count":1},"k-90aac7b0cf5638bf":{"id":"k-90aac7b0cf5638bf","mode":"k","type":"观点与论证","title":"山水林田湖草沙一体化保护和系统治理","qs":[],"count":1},"k-8ce8da4833e746e4":{"id":"k-8ce8da4833e746e4","mode":"k","type":"事实与事件","title":"2023年生态环境保护三类压力尚未根本缓解","qs":[],"count":1},"k-489820be3080ddbf":{"id":"k-489820be3080ddbf","mode":"k","type":"事实与事件","title":"新时代生态文明建设由被动应对到主动作为","qs":[],"count":1},"k-210922a2598d0ba7":{"id":"k-210922a2598d0ba7","mode":"k","type":"事实与事件","title":"2023年支持高质量共建“一带一路”八项行动","qs":[],"count":1},"k-83fc3e52381c71f6":{"id":"k-83fc3e52381c71f6","mode":"k","type":"事实与事件","title":"2023年继续实施“一带一路”科技创新行动计划","qs":[],"count":2}},"questions":{}};
